#!/usr/bin/env python3
# Generated by Cursor
# Edited by Cursor: thin main for lintok; registry/scan/io in separate modules.
"""
Scan transcripts for rule categories (vote_tally, years, roman_numerals, etc.).

Group by (rule_id, span), apply normalization, write per-rule JSON in unified schema.
"""

import argparse
import time
from collections import defaultdict
from pathlib import Path

from scripts.build_rule_candidates_io import write_rule_candidate_files
from scripts.build_rule_candidates_registry import (
    ALL_RULE_IDS,
    RULE_NORMALIZER,
    SCANNER_NAME_TO_RULE_IDS,
)
from scripts.build_rule_candidates_scan import run_global_counts_first_pass, run_scan
from scripts.dictionary_loader import set_allow_no_enchant
from scripts.rule_normalizations import normalize_latin_batch


def main() -> None:
    """Build rule candidate JSON files from transcripts (unified schema)."""
    parser = argparse.ArgumentParser(
        description="Build rule correction candidates from transcripts (unified schema)."
    )
    parser.add_argument(
        "-i",
        "--input",
        type=Path,
        default=Path("data/transcripts"),
        help="Transcripts directory (recursive *.json)",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=Path("data"),
        help="Output directory for <rule_id>_candidates.json",
    )
    parser.add_argument(
        "--profile",
        type=int,
        default=0,
        metavar="N",
        help="If N>0, process first N transcripts only and print per-scanner CPU time (then exit without writing).",
    )
    parser.add_argument(
        "--profile-report",
        type=Path,
        default=None,
        metavar="PATH",
        help="When using --profile, write a markdown report to this path (default: docs/rule_timing_report.md).",
    )
    parser.add_argument(
        "--allow-no-enchant",
        action="store_true",
        help="Allow fallback to word list when enchant (spell checker) is unavailable. By default, raise an error.",
    )
    args = parser.parse_args()
    set_allow_no_enchant(getattr(args, "allow_no_enchant", False))
    transcripts_dir = args.input
    out_dir = args.output
    if not transcripts_dir.is_dir():
        print(f"Input directory not found: {transcripts_dir}")
        raise SystemExit(1)
    out_dir.mkdir(parents=True, exist_ok=True)

    profile_n = getattr(args, "profile", 0) or 0
    paths_list = sorted(transcripts_dir.rglob("*.json"))
    if profile_n > 0:
        paths_list = paths_list[:profile_n]

    global_counts = run_global_counts_first_pass(paths_list)
    groups, typo_corrections, profile_times = run_scan(
        transcripts_dir, paths_list, profile_n, global_counts
    )

    if profile_n:
        normalize_times: dict[str, float] = defaultdict(float)
        for rule_id in ALL_RULE_IDS:
            unique_spans = [span for (rid, span) in groups if rid == rule_id]
            if not unique_spans:
                continue
            if rule_id == "latin_extended":
                t0 = time.perf_counter()
                normalize_latin_batch(sorted(set(unique_spans)))
                normalize_times[rule_id] = time.perf_counter() - t0
                continue
            normalizer = RULE_NORMALIZER.get(rule_id)
            if not normalizer:
                continue
            t0 = time.perf_counter()
            for span in unique_spans:
                normalizer(span)
            normalize_times[rule_id] = time.perf_counter() - t0

        rule_scan_times: dict[str, float] = defaultdict(float)
        for scanner_name, scan_time in profile_times.items():
            rule_ids = SCANNER_NAME_TO_RULE_IDS.get(scanner_name)
            if not rule_ids:
                continue
            per_rule = scan_time / len(rule_ids)
            for rid in rule_ids:
                rule_scan_times[rid] += per_rule

        rule_totals: dict[str, float] = {}
        for rule_id in ALL_RULE_IDS:
            rule_totals[rule_id] = rule_scan_times.get(
                rule_id, 0
            ) + normalize_times.get(rule_id, 0)
        total_all = sum(rule_totals.values())
        sorted_rules = sorted(rule_totals.keys(), key=lambda k: -rule_totals[k])

        print(
            "Profile (first",
            profile_n,
            "transcripts) — per-rule total (scan + normalize):",
        )
        for rule_id in sorted_rules[:20]:
            t = rule_totals[rule_id]
            pct = 100 * t / total_all if total_all else 0
            print(f"  {rule_id}: {t:.2f}s ({pct:.1f}%)")
        if len(sorted_rules) > 20:
            print("  ...")

        report_path = getattr(args, "profile_report", None) or Path(
            "docs/rule_timing_report.md"
        )
        report_path.parent.mkdir(parents=True, exist_ok=True)
        top_rule = sorted_rules[0] if sorted_rules else ""
        top_pct = (
            100 * rule_totals[top_rule] / total_all if total_all and top_rule else 0
        )
        lines = [
            "# Rule timing report",
            "",
            f"All rules in order of total time (scan + normalize, first {profile_n} transcripts).",
            "",
            "## Bottlenecks (how to speed up)",
            "",
            f"- **{top_rule}** (≈{top_pct:.0f}% of total): "
            + (
                "Uroman is run once per language over unified text (all Latin spans, newline-separated). "
                "Set `UROMAN_FAST=1` to run only default uroman (no per-language)."
                if top_rule == "latin_extended"
                else "Consider optimizing scan or normalizer for this rule."
            ),
            "",
            "| Rank | Rule | Scan (s) | Normalize (s) | Total (s) | % |",
            "| ---:| --- | ---: | ---: | ---: | ---: |",
        ]
        for rank, rule_id in enumerate(sorted_rules, 1):
            scan_t = rule_scan_times.get(rule_id, 0)
            norm_t = normalize_times.get(rule_id, 0)
            t = rule_totals[rule_id]
            pct = 100 * t / total_all if total_all else 0
            lines.append(
                f"| {rank} | {rule_id} | {scan_t:.2f} | {norm_t:.2f} | {t:.2f} | {pct:.1f} |"
            )
        report_path.write_text("\n".join(lines) + "\n")
        print(f"Wrote report to {report_path}")
        return

    latin_spans = sorted(set(span for (rid, span) in groups if rid == "latin_extended"))
    latin_corrections_map: dict[str, list] = {}
    if latin_spans:
        batch_results = normalize_latin_batch(latin_spans)
        latin_corrections_map = dict(zip(latin_spans, batch_results, strict=False))

    write_rule_candidate_files(out_dir, groups, typo_corrections, latin_corrections_map)
    print(f"Wrote {len(ALL_RULE_IDS)} rule candidate files to {out_dir}")


if __name__ == "__main__":
    main()
